import { MakeLogicType, actions, connect, kea, path, reducers, selectors } from 'kea'

import { FeatureFlagsSet, featureFlagLogic } from 'lib/logic/featureFlagLogic'
import { getProductAccessDisabledReason } from 'lib/utils/accessControlUtils'
import { isFileSystemImportFlagEnabled } from 'lib/utils/fileSystemImportFlags'

import { projectTreeDataLogic } from '~/layout/panel-layout/ProjectTree/projectTreeDataLogic'
import { FileSystemImport } from '~/queries/schema/schema-general'

import { ToolGroup, getToolSourceItems, groupTools, isToolItem, toolLabel } from './toolsUtils'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface toolsLogicValues {
    featureFlags: FeatureFlagsSet // featureFlagLogic
    groupItems: FileSystemImport[] // projectTreeDataLogic
    productPages: FileSystemImport[]
    search: string
    toolGroups: ToolGroup[]
    tools: FileSystemImport[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface toolsLogicActions {
    setSearch: (search: string) => {
        search: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface toolsLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        productPages: (featureFlags: FeatureFlagsSet, groupItems: FileSystemImport[]) => FileSystemImport[]
        tools: (productPages: FileSystemImport[]) => FileSystemImport[]
        toolGroups: (tools: FileSystemImport[], search: string) => ToolGroup[]
    }
}

export type toolsLogicType = MakeLogicType<toolsLogicValues, toolsLogicActions, Record<string, any>, toolsLogicMeta>

export const toolsLogic = kea<toolsLogicType>([
    path(['scenes', 'tools', 'toolsLogic']),
    connect(() => ({ values: [featureFlagLogic, ['featureFlags'], projectTreeDataLogic, ['groupItems']] })),
    actions({ setSearch: (search: string) => ({ search }) }),
    reducers({ search: ['', { setSearch: (_, { search }) => search }] }),
    selectors({
        // Every product page this user can open, Library pages included. Recently viewed draws from these.
        productPages: [
            (s) => [s.featureFlags, s.groupItems],
            (featureFlags: FeatureFlagsSet, groupItems: FileSystemImport[]): FileSystemImport[] => {
                const seen = new Set<string>()
                // Saved group views are shortcuts to filtered pages, so only the group type pages join the list.
                const groupPages = groupItems.filter((item) => !item.shortcut)
                return [...getToolSourceItems(), ...groupPages]
                    .filter((item) => {
                        if (
                            !item.href ||
                            seen.has(item.href) ||
                            !isFileSystemImportFlagEnabled(item, featureFlags) ||
                            getProductAccessDisabledReason(item)
                        ) {
                            return false
                        }
                        seen.add(item.href)
                        return true
                    })
                    .sort((first, second) => toolLabel(first).localeCompare(toolLabel(second)))
            },
        ],
        tools: [
            (s) => [s.productPages],
            (productPages: FileSystemImport[]): FileSystemImport[] => productPages.filter(isToolItem),
        ],
        toolGroups: [
            (s) => [s.tools, s.search],
            (tools: FileSystemImport[], search: string): ToolGroup[] => groupTools(tools, search),
        ],
    }),
])
